from __future__ import annotations

import base64
import gzip
import hashlib
from pathlib import Path
import zipfile

SETTING_GZIP_B64 = ""

FIXED_DATE = (2026, 10, 2, 0, 0, 0)


def _entry(name: str, data: bytes) -> zipfile.ZipInfo:
    info = zipfile.ZipInfo(name, FIXED_DATE)
    info.compress_type = zipfile.ZIP_DEFLATED
    info.external_attr = 0o100644 << 16
    return info


def build(repo_root: Path) -> Path:
    repo_root = Path(repo_root)
    source = repo_root / "backend" / "assets" / "resolve_titles" / "KURA_paper_title_v8.drfx"
    target = repo_root / "backend" / "assets" / "resolve_titles" / "KURA_paper_title_v9.drfx"
    setting = gzip.decompress(base64.b64decode(SETTING_GZIP_B64))
    with zipfile.ZipFile(source) as archive:
        paper = archive.read("Edit/Titles/KURA_paper_title_v8/paper.jpg")
    setting_name = "Edit/Titles/KURA_paper_title_v9/KURA_paper_title_v9.setting"
    paper_name = "Edit/Titles/KURA_paper_title_v9/paper.jpg"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.unlink(missing_ok=True)
    with zipfile.ZipFile(target, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        archive.writestr(_entry(setting_name, setting), setting)
        archive.writestr(_entry(paper_name, paper), paper)
    print(f"{target} {target.stat().st_size} bytes sha256={hashlib.sha256(target.read_bytes()).hexdigest()}")
    return target


if __name__ == "__main__":
    build(Path(__file__).resolve().parents[1])
